def _check(value, name):
    if not isinstance(value, int) or isinstance(value, bool) or value < 1:
        raise ValueError("%s must be an int of at least 1" % name)


def chunk(items, size):
    _check(size, "size")
    return [list(items[i:i + size]) for i in range(0, len(items), size)]


def sliding(items, size, step=1):
    _check(size, "size")
    _check(step, "step")
    result = []
    start = 0
    n = len(items)
    while start + size <= n:
        result.append(list(items[start:start + size]))
        start += step
    return result
